css:
.loader { position: relative; display: inline-block; width: var(--loader-size); height: var(--loader-size); }
.loader .arrow { position: absolute; left: 50%; top: 14%; width: calc(var(--loader-size) * .09); height: 44%; margin-left: calc(var(--loader-size) * -.045); border-radius: 9999px; background: var(--loader-color); animation: twUp calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
.loader .arrow::before { content: ''; position: absolute; top: calc(var(--loader-size) * -.02); left: 50%; width: calc(var(--loader-size) * .22); height: calc(var(--loader-size) * .22); margin-left: calc(var(--loader-size) * -.11); border-top: calc(var(--loader-size) * .09) solid var(--loader-color); border-left: calc(var(--loader-size) * .09) solid var(--loader-color); border-radius: calc(var(--loader-size) * .03); transform: rotate(45deg); }
.loader .tray { position: absolute; left: 14%; bottom: 10%; width: 72%; height: 22%; border: calc(var(--loader-size) * .06) solid color-mix(in srgb, var(--loader-color) 45%, transparent); border-top: 0; border-radius: 0 0 calc(var(--loader-size) * .1) calc(var(--loader-size) * .1); box-sizing: border-box; }
@keyframes twUp { 0%, 100% { transform: translateY(20%); opacity: .45; } 50% { transform: translateY(-8%); opacity: 1; } }
